//! Outer code: shortened Reed–Solomon (204,188) (ARIB STD-B31 §3.3).
//!
//! > "The shortened (204,188) Reed-Solomon code is generated by adding
//! > 51-byte 00HEX at the beginning of the 188-byte input data bytes,
//! > processing with the (255,239) Reed-Solomon code, and then removing
//! > these 51 bytes." — §3.3
//!
//! Field: GF(2⁸) with p(x) = x⁸ + x⁴ + x³ + x² + 1 (0x11D); generator
//! g(x) = (x − λ⁰)(x − λ¹)…(x − λ¹⁵), λ = 02HEX (§3.3).
//!
//! Byte ↔ polynomial mapping: the first byte of the 204-byte transmission
//! TSP is the coefficient of x²⁰³ (highest degree) and the 16 parity bytes
//! are the coefficients of x¹⁵…x⁰. This is the only mapping under which
//! prepending 51 zero bytes "at the beginning" yields a (255,239) codeword
//! with the parity at the end as in Fig. 3-6 (b) — see SPEC-NOTES.md.
//!
//! The code itself (field, generator, encoder and the errors-only t = 8
//! decoder) is `isdb_fec::rs`, shared with ISDB-S; this module keeps the
//! 188/204-byte API of the ISDB-T chain.

use crate::FecError;
use isdb_fec::rs::RS_204_188;
use isdbt_core::{TRANSMISSION_TSP, TSP};

pub use isdb_fec::rs::{ALPHA, PRIMITIVE_POLY, generator_poly, gf_alpha_pow, gf_mul};

/// Number of RS parity bytes (§3.3: 204 − 188).
pub const PARITY: usize = TRANSMISSION_TSP - TSP;
/// Correctable byte errors, t = 8 (§3.3 \[Description\]: "can correct up to
/// 8 random bytes in error among 204 bytes").
pub const T: usize = PARITY / 2;
/// Zero bytes conceptually prepended to shorten RS(255,239) (§3.3).
pub const SHORTENING: usize = 255 - TRANSMISSION_TSP;

const _: () = assert!(PARITY == isdb_fec::rs::PARITY && RS_204_188.n() == TRANSMISSION_TSP);

/// Systematic RS(204,188) encoding of one 188-byte TSP (§3.3, Fig. 3-6):
/// returns the transmission TSP = the 188 input bytes followed by the 16
/// parity bytes r(x) = d(x)·x¹⁶ mod g(x).
pub fn encode(tsp: &[u8; TSP]) -> [u8; TRANSMISSION_TSP] {
    let mut out = [0u8; TRANSMISSION_TSP];
    out[..TSP].copy_from_slice(tsp);
    out[TSP..].copy_from_slice(&RS_204_188.parity(tsp));
    out
}

/// The 16 syndromes S_j = c(λ^j), j = 0..15, of a 204-byte word (roots of
/// g(x), §3.3). All zero ⇔ the word is a codeword.
pub fn syndromes(word: &[u8; TRANSMISSION_TSP]) -> [u8; PARITY] {
    RS_204_188.syndromes(word)
}

/// Successful RS decoding outcome.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Corrected {
    /// Number of byte errors corrected (0..=8).
    pub errors: usize,
}

/// Decode a received transmission TSP in place (§3.3, t = 8). On success the
/// word is a codeword and the number of corrected bytes is returned; on
/// failure (more than 8 errors detected) the word is left unchanged.
pub fn decode(word: &mut [u8; TRANSMISSION_TSP]) -> Result<Corrected, FecError> {
    RS_204_188
        .decode(word)
        .map(|errors| Corrected { errors })
        .map_err(|_| FecError::RsUncorrectable)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::testutil::XorShift;

    /// §3.3: λ = 2 generates GF(2⁸)* under p(x) = 0x11D (order 255).
    #[test]
    fn spec_3_3_primitive_element() {
        let mut seen = [false; 256];
        for e in 0..255 {
            let v = gf_alpha_pow(e);
            assert!(!seen[v as usize], "λ^{e} repeats");
            seen[v as usize] = true;
        }
        assert_eq!(gf_alpha_pow(8), 0x1D, "λ⁸ = λ⁴+λ³+λ²+1");
        assert_eq!(gf_alpha_pow(255), 1);
    }

    /// §3.3: g(x) has exactly the roots λ⁰..λ¹⁵ and is monic of degree 16.
    #[test]
    fn spec_3_3_generator_roots() {
        let g = generator_poly();
        assert_eq!(g[0], 1);
        let eval = |x: u8| g.iter().fold(0u8, |acc, &c| gf_mul(acc, x) ^ c);
        for i in 0..255u32 {
            let v = eval(gf_alpha_pow(i));
            if i < 16 {
                assert_eq!(v, 0, "λ^{i} must be a root");
            } else {
                assert_ne!(v, 0, "λ^{i} must not be a root");
            }
        }
        assert_ne!(eval(0), 0);
    }

    /// §3.3: shortened encoding equals the (255,239) systematic encoding of
    /// 51 zero bytes + data with those 51 bytes removed (checked by long
    /// division over the full 255-byte word).
    #[test]
    fn spec_3_3_shortening_equivalence() {
        let mut rng = XorShift::new(7);
        let g = generator_poly();
        for _ in 0..20 {
            let mut d = [0u8; TSP];
            rng.fill(&mut d);
            let c = encode(&d);
            let mut full = vec![0u8; SHORTENING];
            full.extend_from_slice(&c);
            assert_eq!(full.len(), 255);
            // remainder of full(x) / g(x) must be 0
            let mut rem = full.clone();
            for i in 0..(255 - PARITY) {
                let f = rem[i];
                if f != 0 {
                    for k in 0..=PARITY {
                        rem[i + k] ^= gf_mul(f, g[k]);
                    }
                }
            }
            assert!(rem.iter().all(|&x| x == 0));
            assert_eq!(&c[..TSP], &d[..]);
        }
    }

    /// Codewords have zero syndromes (§3.3); the all-0x47-sync example
    /// null packet is encodable; ≤ 8 random byte errors are corrected.
    #[test]
    fn spec_3_3_correct_up_to_8() {
        let mut rng = XorShift::new(1);
        for nerr in 0..=T {
            for _ in 0..50 {
                let mut d = [0u8; TSP];
                rng.fill(&mut d);
                d[0] = 0x47;
                let c = encode(&d);
                assert!(syndromes(&c).iter().all(|&x| x == 0));
                let mut r = c;
                let pos = rng.distinct(nerr, TRANSMISSION_TSP);
                for &p in &pos {
                    r[p] ^= (rng.next() as u8).max(1);
                }
                let out = decode(&mut r).expect("≤8 errors must decode");
                assert_eq!(out.errors, nerr);
                assert_eq!(r, c);
            }
        }
    }

    /// Beyond t = 8 the decoder must not silently return the transmitted
    /// word; with this fixed seed every case is detected as uncorrectable.
    #[test]
    fn spec_3_3_failure_beyond_8() {
        let mut rng = XorShift::new(99);
        let mut detected = 0;
        let trials = 300;
        for i in 0..trials {
            let mut d = [0u8; TSP];
            rng.fill(&mut d);
            let c = encode(&d);
            let mut r = c;
            let nerr = 9 + i % 12;
            for &p in &rng.distinct(nerr, TRANSMISSION_TSP) {
                r[p] ^= (rng.next() as u8).max(1);
            }
            let before = r;
            match decode(&mut r) {
                Err(_) => {
                    assert_eq!(r, before, "failed decode must not modify");
                    detected += 1;
                }
                Ok(_) => {
                    // Miscorrection to another codeword (probability ~1e-5).
                    assert!(syndromes(&r).iter().all(|&x| x == 0));
                    assert_ne!(r, c);
                }
            }
        }
        assert_eq!(detected, trials);
    }
}
